SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;

DROP DATABASE IF EXISTS CelestialDatabase;
CREATE DATABASE CelestialDatabase CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE CelestialDatabase;

CREATE TABLE BodyType (
  BodyTypeID INT AUTO_INCREMENT PRIMARY KEY,
  TypeName VARCHAR(50) NOT NULL UNIQUE,
  Description VARCHAR(255) NULL
) ENGINE=InnoDB;

CREATE TABLE Constellation (
  ConstellationID INT AUTO_INCREMENT PRIMARY KEY,
  Name VARCHAR(50) NOT NULL UNIQUE,
  Abbreviation VARCHAR(5) NULL,
  Genitive VARCHAR(50) NULL,
  VisibleFromNorthern TINYINT(1) NOT NULL DEFAULT 1
) ENGINE=InnoDB;

CREATE TABLE CelestialBody (
  BodyID BIGINT AUTO_INCREMENT PRIMARY KEY,
  Name VARCHAR(100) NOT NULL,
  CommonName VARCHAR(100) NULL,
  BodyTypeID INT NOT NULL,
  Magnitude DECIMAL(6,2) NULL,
  RA_Hours DECIMAL(10,6) NULL,
  DEC_Degrees DECIMAL(9,6) NULL,
  Distance_LY DECIMAL(18,6) NULL,
  ConstellationID INT NULL,
  Description TEXT NULL,
  DiscoveredBy VARCHAR(100) NULL,
  DiscoveryYear INT NULL,
  CreatedAt DATETIME NULL,
  UpdatedAt DATETIME NULL,
  RA_Degrees DECIMAL(10,6) GENERATED ALWAYS AS (RA_Hours*15) STORED,
  FOREIGN KEY (BodyTypeID) REFERENCES BodyType(BodyTypeID),
  FOREIGN KEY (ConstellationID) REFERENCES Constellation(ConstellationID),
  INDEX IX_Magnitude (Magnitude),
  INDEX IX_RA_DEC (RA_Hours, DEC_Degrees),
  INDEX IX_Type (BodyTypeID),
  INDEX IX_Name (Name)
) ENGINE=InnoDB;

CREATE TABLE Star (
  BodyID BIGINT PRIMARY KEY,
  SpectralType VARCHAR(30) NULL,
  SurfaceTempK INT NULL,
  LuminositySolar DECIMAL(18,6) NULL,
  MassSolar DECIMAL(18,6) NULL,
  RadiusSolar DECIMAL(18,6) NULL,
  ParallaxMas DECIMAL(12,6) NULL,
  ProperMotionRA DECIMAL(12,6) NULL,
  ProperMotionDec DECIMAL(12,6) NULL,
  FOREIGN KEY (BodyID) REFERENCES CelestialBody(BodyID) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE Planet (
  BodyID BIGINT PRIMARY KEY,
  PlanetClass VARCHAR(50) NULL,
  MassEarth DECIMAL(18,6) NULL,
  RadiusEarth DECIMAL(18,6) NULL,
  OrbitalPeriodDays DECIMAL(18,6) NULL,
  SemiMajorAxisAU DECIMAL(18,6) NULL,
  Eccentricity DECIMAL(10,8) NULL,
  InclinationDeg DECIMAL(8,4) NULL,
  RotationPeriodHrs DECIMAL(12,6) NULL,
  HasRings TINYINT(1) NULL,
  Atmosphere VARCHAR(255) NULL,
  FOREIGN KEY (BodyID) REFERENCES CelestialBody(BodyID) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE Moon (
  BodyID BIGINT PRIMARY KEY,
  ParentBodyID BIGINT NOT NULL,
  DiameterKm DECIMAL(12,3) NULL,
  MassKg DECIMAL(30,6) NULL,
  OrbitalPeriodDays DECIMAL(12,6) NULL,
  SemiMajorAxisKm DECIMAL(18,3) NULL,
  FOREIGN KEY (BodyID) REFERENCES CelestialBody(BodyID) ON DELETE CASCADE,
  FOREIGN KEY (ParentBodyID) REFERENCES CelestialBody(BodyID)
) ENGINE=InnoDB;

CREATE TABLE Asteroid (
  BodyID BIGINT PRIMARY KEY,
  AsteroidClass VARCHAR(50) NULL,
  DiameterKm DECIMAL(12,3) NULL,
  OrbitalPeriodDays DECIMAL(12,6) NULL,
  SemiMajorAxisAU DECIMAL(12,6) NULL,
  Eccentricity DECIMAL(10,8) NULL,
  InclinationDeg DECIMAL(8,4) NULL,
  Albedo DECIMAL(6,4) NULL,
  FOREIGN KEY (BodyID) REFERENCES CelestialBody(BodyID) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE Comet (
  BodyID BIGINT PRIMARY KEY,
  CometType VARCHAR(50) NULL,
  OrbitalPeriodYears DECIMAL(12,6) NULL,
  PerihelionAU DECIMAL(12,6) NULL,
  AphelionAU DECIMAL(12,6) NULL,
  InclinationDeg DECIMAL(8,4) NULL,
  Eccentricity DECIMAL(10,8) NULL,
  LastPerihelion DATE NULL,
  NextPerihelion DATE NULL,
  FOREIGN KEY (BodyID) REFERENCES CelestialBody(BodyID) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE MessierObject (
  BodyID BIGINT PRIMARY KEY,
  MessierNumber INT NOT NULL UNIQUE,
  NGCNumber INT NULL,
  ObjectType VARCHAR(50) NULL,
  Distance_KLY DECIMAL(12,3) NULL,
  ApparentSizeArcmin DECIMAL(8,2) NULL,
  FOREIGN KEY (BodyID) REFERENCES CelestialBody(BodyID) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE DeepSkyObject (
  BodyID BIGINT PRIMARY KEY,
  Catalogue VARCHAR(20) NULL,
  CatalogueNumber VARCHAR(20) NULL,
  ObjectType VARCHAR(50) NULL,
  Distance_KLY DECIMAL(12,3) NULL,
  ApparentSizeArcmin DECIMAL(8,2) NULL,
  FOREIGN KEY (BodyID) REFERENCES CelestialBody(BodyID) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE Observation (
  ObservationID BIGINT AUTO_INCREMENT PRIMARY KEY,
  BodyID BIGINT NOT NULL,
  ObservedAt DATETIME NOT NULL,
  Location VARCHAR(100) NULL,
  Seeing VARCHAR(50) NULL,
  Instrument VARCHAR(100) NULL,
  Notes TEXT NULL,
  FOREIGN KEY (BodyID) REFERENCES CelestialBody(BodyID) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE VIEW vw_CelestialBodySummary AS
SELECT cb.BodyID, cb.Name, cb.CommonName, bt.TypeName AS BodyType, cb.Magnitude,
  cb.RA_Hours, cb.RA_Degrees, cb.DEC_Degrees, cb.Distance_LY, c.Name AS Constellation
FROM CelestialBody cb
JOIN BodyType bt ON bt.BodyTypeID=cb.BodyTypeID
LEFT JOIN Constellation c ON c.ConstellationID=cb.ConstellationID;

CREATE VIEW vw_MoonsWithPlanets AS
SELECT m.Name AS Moon, p.Name AS OrbitsPlanet
FROM CelestialBody m
JOIN Moon mn ON mn.BodyID=m.BodyID
JOIN CelestialBody p ON p.BodyID=mn.ParentBodyID;

SET FOREIGN_KEY_CHECKS=1;


-- DATA --

SET FOREIGN_KEY_CHECKS=1;
